const body = $json.body ?? $json;

const runMode = String(body.runMode ?? 'on_demand').trim();
const arxivCategory = String(body.arxivCategory ?? 'cs.AI').trim();
const maxResultsRaw = Number(body.maxResults ?? 8);
const maxResults = Number.isFinite(maxResultsRaw) ? Math.max(1, Math.min(8, Math.floor(maxResultsRaw))) : 8;

const defaultSourceBase = 'https://export.arxiv.org/api/query';
const defaultReferenceUrl = 'http://reference_site/edge-ai-taxonomy.json';
const fallbackReferenceUrl = 'http://host.docker.internal:8090/edge-ai-taxonomy.json';

const sourceUrlBase = String(body.sourceUrl ?? defaultSourceBase).trim();
const referenceUrlRaw = String(body.referenceUrl ?? defaultReferenceUrl).trim();

const isValidUrl = (value) => /^https?:\/\/[^\s/$.?#].[^\s]*$/i.test(value);
if (!isValidUrl(sourceUrlBase)) {
  throw new Error(`sourceUrl must be a valid http/https URL. Received: '${sourceUrlBase}'`);
}
if (!isValidUrl(referenceUrlRaw)) {
  throw new Error(`referenceUrl must be a valid http/https URL. Received: '${referenceUrlRaw}'`);
}

const hasQuery = sourceUrlBase.includes('?');
const sourceUrl = `${sourceUrlBase}${hasQuery ? '&' : '?'}search_query=cat:${encodeURIComponent(arxivCategory)}&sortBy=submittedDate&sortOrder=descending&max_results=${maxResults}`;

const uuidv4 = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (char) => {
  const r = Math.floor(Math.random() * 16);
  const v = char === 'x' ? r : (r & 0x3) | 0x8;
  return v.toString(16);
});

const escapeSql = (value) => String(value).replace(/'/g, "''");
const jobId = uuidv4();

const inputPayload = {
  profileId: String(body.profileId ?? 'arxiv_edge_ai').trim(),
  sourceUrlBase,
  referenceUrl: referenceUrlRaw,
  runMode,
  inputs: {
    arxivCategory,
    maxResults
  }
};

return [{
  json: {
    jobId,
    profileId: inputPayload.profileId,
    profileIdSql: escapeSql(inputPayload.profileId),
    inputPayload,
    inputPayloadSql: escapeSql(JSON.stringify(inputPayload)),
    runMode,
    arxivCategory,
    maxResults,
    sourceUrl,
    referenceUrl: referenceUrlRaw,
    fallbackReferenceUrl,
    sourceUrlSql: escapeSql(sourceUrl),
    referenceUrlSql: escapeSql(referenceUrlRaw),
    runModeSql: escapeSql(runMode)
  }
}];

const base = $node['Validate + Build Job'].json;
const arxivNode = $node['Fetch arXiv Feed'].json ?? {};
const arxivRaw = String(arxivNode.body ?? arxivNode.data ?? arxivNode.responseBody ?? '');
const arxivStatus = Number(arxivNode.statusCode ?? arxivNode.status ?? 0);
const taxonomyResponse = $json.body ?? $json;

if (arxivStatus >= 400) {
  throw new Error(`arXiv fetch failed with status ${arxivStatus}`);
}
if (!arxivRaw) {
  throw new Error(`arXiv response body is empty. Node keys: ${Object.keys(arxivNode).join(', ')}`);
}

const normalizedXml = arxivRaw
  .replace(/<atom:entry/gi, '<entry')
  .replace(/<\/atom:entry>/gi, '</entry>');

const stripXml = (value) => String(value)
  .replace(/<!\[CDATA\[(.*?)\]\]>/gs, '$1')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const firstTagValue = (block, tag) => {
  const re = new RegExp(`<(?:\\w+:)?${tag}[^>]*>([\\s\\S]*?)<\\/(?:\\w+:)?${tag}>`, 'i');
  const match = block.match(re);
  return match ? stripXml(match[1]) : '';
};

const entryBlocks = normalizedXml.match(/<(?:\w+:)?entry\b[\s\S]*?<\/(?:\w+:)?entry>/gi) ?? [];
if (!entryBlocks.length) {
  const preview = normalizedXml.slice(0, 220).replace(/\s+/g, ' ');
  throw new Error(`arXiv response did not contain parsable entries. Preview: ${preview}`);
}

const papers = entryBlocks.slice(0, base.maxResults).map((entry) => {
  const idRaw = firstTagValue(entry, 'id');
  const title = firstTagValue(entry, 'title');
  const abstract = firstTagValue(entry, 'summary');
  const published = firstTagValue(entry, 'published');
  const updated = firstTagValue(entry, 'updated');
  const id = idRaw.split('/abs/').pop() || idRaw;
  return { id, title, abstract, published, updated };
}).filter((p) => p.title && p.abstract);

if (!papers.length) {
  throw new Error('No valid papers were parsed from arXiv entries.');
}

const positiveSignals = taxonomyResponse?.positive_signals ?? {};
const subdomains = Array.isArray(taxonomyResponse?.subdomains) ? taxonomyResponse.subdomains : [];

const payload = {
  phase: 'cp5',
  source: {
    site: 'arxiv',
    category: base.arxivCategory,
    maxResultsRequested: base.maxResults,
    parsedCount: papers.length
  },
  reference: {
    title: taxonomyResponse?.title ?? 'Edge AI Classification Taxonomy',
    version: taxonomyResponse?.version ?? 'unknown',
    category: taxonomyResponse?.category ?? 'edge_ai',
    strongSignals: positiveSignals?.strong_keywords ?? [],
    mediumSignals: positiveSignals?.medium_keywords ?? [],
    subdomains
  },
  papers
};

const payloadText = JSON.stringify(payload);
const escapeSql = (value) => String(value).replace(/'/g, "''");

return [{
  json: {
    ...base,
    papersCount: papers.length,
    taxonomyVersion: payload.reference.version,
    firstPaperTitle: papers[0]?.title ?? '',
    payloadJsonSql: escapeSql(payloadText),
    payloadSummarySql: escapeSql(`Prepared ${papers.length} papers from arXiv category ${base.arxivCategory} with taxonomy ${payload.reference.version}`),
    preparedPayload: payload
  }
}];

const base = $node['Validate + Build Job'].json;
const parsed = $node['Parse + Prepare Payload'].json;
const payload = parsed.preparedPayload ?? null;
if (!payload || typeof payload !== 'object') {
  throw new Error('Prepared payload not found for this jobId. Ensure CP5 completed successfully.');
}

const papersRaw = Array.isArray(payload.papers) ? payload.papers : [];
const llmPaperLimit = Math.max(1, Math.min(8, Number(base.maxResults ?? 8)));
const papers = papersRaw.slice(0, llmPaperLimit).map((p) => ({
  paper_id: String(p.id ?? '').trim(),
  title: String(p.title ?? '').trim(),
  abstract: String(p.abstract ?? '').trim().slice(0, 2000),
  published: String(p.published ?? '').trim()
})).filter((p) => p.paper_id && p.title && p.abstract);

if (!papers.length) {
  throw new Error('Prepared payload has no valid papers to classify.');
}

const reference = payload.reference ?? {};
const taxonomy = {
  category: reference.category ?? 'edge_ai',
  strongSignals: Array.isArray(reference.strongSignals) ? reference.strongSignals : [],
  mediumSignals: Array.isArray(reference.mediumSignals) ? reference.mediumSignals : [],
  subdomains: Array.isArray(reference.subdomains) ? reference.subdomains : []
};

const provider = String($env.MODEL_PROVIDER ?? 'openai').trim().toLowerCase();

let llmUrl = '';
let authHeader = '';
let apiKeyHeader = '';
let modelName = '';

const systemPrompt = [
  'You are an expert classifier for Edge AI research papers.',
  'Classify each paper into edge_ai (true/false).',
  'Use the taxonomy signals and paper text only.',
  'IMPORTANT: confidence means probability that the paper IS Edge AI (0..1).',
  'If is_edge_ai is true, confidence must be >= 0.5. If is_edge_ai is false, confidence must be < 0.5.',
  'Return strict JSON only, no markdown.',
  'Output schema: {"classifications":[{"paper_id":"string","is_edge_ai":true,"edge_ai_subdomain":"string|null","confidence":0.0,"evidence":["string"]}]}'
].join(' ');

const userPayload = {
  task: 'Classify arXiv papers for Edge AI relevance',
  taxonomy,
  papers
};

let llmRequestBody;

if (provider === 'openai') {
  const openaiApiKey = String($env.OPENAI_API_KEY ?? '').trim();
  const openaiModel = String($env.OPENAI_MODEL ?? 'gpt-4.1-mini').trim();

  if (!openaiApiKey || !openaiModel) {
    throw new Error('OpenAI env vars are missing. Set OPENAI_API_KEY and OPENAI_MODEL in Template_1/.env and restart n8n container.');
  }

  llmUrl = 'https://api.openai.com/v1/chat/completions';
  authHeader = `Bearer ${openaiApiKey}`;
  modelName = openaiModel;

  llmRequestBody = {
    model: openaiModel,
    temperature: 0.1,
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: JSON.stringify(userPayload) }
    ]
  };
} else if (provider === 'azure_openai') {
  const endpoint = String($env.AZURE_OPENAI_ENDPOINT ?? '').trim().replace(/\/$/, '');
  const deployment = String($env.AZURE_OPENAI_DEPLOYMENT ?? '').trim();
  const apiVersion = String($env.AZURE_OPENAI_API_VERSION ?? '2024-10-21').trim();
  const apiKey = String($env.AZURE_OPENAI_API_KEY ?? '').trim();

  if (!endpoint || !deployment || !apiVersion || !apiKey) {
    throw new Error('Azure OpenAI env vars are missing. Set AZURE_OPENAI_ENDPOINT, AZURE_OPENAI_DEPLOYMENT, AZURE_OPENAI_API_VERSION, AZURE_OPENAI_API_KEY in Template_1/.env and restart n8n container.');
  }

  llmUrl = `${endpoint}/openai/deployments/${deployment}/chat/completions?api-version=${encodeURIComponent(apiVersion)}`;
  apiKeyHeader = apiKey;
  modelName = deployment;

  llmRequestBody = {
    temperature: 0.1,
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: JSON.stringify(userPayload) }
    ]
  };
} else {
  throw new Error(`Unsupported MODEL_PROVIDER='${provider}'. Use 'openai' or 'azure_openai'.`);
}

const escapeSql = (value) => String(value).replace(/'/g, "''");

return [{
  json: {
    jobId: base.jobId,
    jobIdSql: escapeSql(base.jobId),
    provider,
    providerSql: escapeSql(provider),
    modelName,
    llmUrl,
    authHeader,
    apiKeyHeader,
    llmRequestBody
  }
}];

const req = $node['Build LLM Request'].json;
const resp = $json.body ?? $json;

const contentRaw = resp?.choices?.[0]?.message?.content;
if (!contentRaw) {
  throw new Error(`LLM response content is missing. Keys: ${Object.keys(resp || {}).join(', ')}`);
}

const content = Array.isArray(contentRaw)
  ? String(contentRaw.map((x) => x?.text ?? '').join(''))
  : String(contentRaw);

let parsed;
try {
  parsed = JSON.parse(content);
} catch (err) {
  throw new Error(`LLM returned non-JSON content: ${content.slice(0, 300)}`);
}

const list = Array.isArray(parsed.classifications) ? parsed.classifications : [];
if (!list.length) {
  throw new Error('LLM JSON did not contain classifications array with items.');
}

const normalized = list.map((item) => {
  const declaredLabel = Boolean(item.is_edge_ai);
  const raw = Number(item.confidence);

  // confidence is standardized as P(is_edge_ai=true).
  // Backward compatibility: if model returns decision-confidence semantics, flip when contradictory.
  let edgeAiScore;
  if (Number.isFinite(raw)) {
    edgeAiScore = Math.max(0, Math.min(1, raw));
    const contradictory = (declaredLabel && edgeAiScore < 0.5) || (!declaredLabel && edgeAiScore > 0.5);
    if (contradictory) {
      edgeAiScore = 1 - edgeAiScore;
    }
  } else {
    edgeAiScore = declaredLabel ? 0.75 : 0.25;
  }

  const isEdgeAi = edgeAiScore >= 0.5;

  const evidence = Array.isArray(item.evidence)
    ? item.evidence.map((v) => String(v).trim()).filter(Boolean).slice(0, 3)
    : [];

  return {
    paper_id: String(item.paper_id ?? '').trim(),
    is_edge_ai: isEdgeAi,
    edge_ai_subdomain: isEdgeAi
      ? (item.edge_ai_subdomain == null ? null : String(item.edge_ai_subdomain).trim())
      : null,
    confidence: Number(edgeAiScore.toFixed(4)),
    evidence
  };
}).filter((item) => item.paper_id);

if (!normalized.length) {
  throw new Error('No valid classification rows after normalization.');
}

const positiveCount = normalized.filter((x) => x.is_edge_ai).length;
const negativeCount = normalized.length - positiveCount;

const result = {
  phase: 'cp6',
  provider: req.provider,
  model: req.modelName,
  confidence_semantics: 'probability_of_edge_ai',
  classified_count: normalized.length,
  positive_count: positiveCount,
  negative_count: negativeCount,
  edge_ai_count: positiveCount,
  not_edge_ai_count: negativeCount,
  classifications: normalized
};

const summaryText = `Classified ${normalized.length} papers. positive=${positiveCount}, negative=${negativeCount}`;
const escapeSql = (value) => String(value).replace(/'/g, "''");

return [{
  json: {
    jobId: req.jobId,
    jobIdSql: req.jobIdSql,
    providerSql: escapeSql(req.provider),
    modelNameSql: escapeSql(req.modelName),
    summarySql: escapeSql(summaryText),
    rawResultSql: escapeSql(JSON.stringify(result)),
    classifiedCount: normalized.length,
    positiveCount,
    negativeCount
  }
}];
